# ---------------------------------------------------------------------------
# Film grain engine (35mm emulation for inpainted fills)
# ---------------------------------------------------------------------------

def _gauss_blur_nchw(t: torch.Tensor, sigma: float) -> torch.Tensor:
    """Separable Gaussian blur on an NCHW tensor. Used to give grain a size."""
    k = max(3, int(sigma * 4.0) + 1)
    if k % 2 == 0:
        k += 1
    x = torch.arange(k, device=t.device, dtype=t.dtype) - k // 2
    g = torch.exp(-(x * x) / (2.0 * sigma * sigma))
    g = g / g.sum()
    c = t.shape[1]
    kh = g.view(1, 1, 1, k).expand(c, 1, 1, k)
    kv = g.view(1, 1, k, 1).expand(c, 1, k, 1)
    t = F.conv2d(t, kh, padding=(0, k // 2), groups=c)
    t = F.conv2d(t, kv, padding=(k // 2, 0), groups=c)
    return t


def make_grain_field(
    b: int,
    h: int,
    w: int,
    grain_size: float,
    device,
    dtype,
    generator=None,
):
    """Draw one grain noise field (luma + chroma), blurred to `grain_size`.

    Split out of apply_film_grain_masked so a dual-eye pair can be grained with
    the SAME field in both eyes. Independent per-eye grain has zero interocular
    correlation, which the visual system reads as binocular rivalry — a
    shimmering veil that is genuinely fatiguing over a feature-length watch.
    One shared field sits the grain at the screen plane, which is what a DI
    grain plate applied to a finished stereo pair does anyway.

    Returns (noise_l [b,1,h,w], noise_c [b,3,h,w]), each unit-std.
    """
    if generator is not None:
        noise_l = torch.randn((b, 1, h, w), generator=generator, device=device, dtype=dtype)
        noise_c = torch.randn((b, 3, h, w), generator=generator, device=device, dtype=dtype)
    else:
        noise_l = torch.randn((b, 1, h, w), device=device, dtype=dtype)
        noise_c = torch.randn((b, 3, h, w), device=device, dtype=dtype)
    if grain_size > 0.15:
        noise_l = _gauss_blur_nchw(noise_l, grain_size)
        noise_c = _gauss_blur_nchw(noise_c, grain_size)
        noise_l = noise_l / noise_l.std().clamp_min(1e-6)
        noise_c = noise_c / noise_c.std().clamp_min(1e-6)
    return noise_l, noise_c


def apply_film_grain_masked(
    frames: torch.Tensor,
    mask: torch.Tensor,
    amount: float,
    grain_size: float = 1.2,
    luma_falloff: float = 0.6,
    chroma_amount: float = 0.12,
    generator=None,
    noise=None,
) -> torch.Tensor:
    """35mm-style grain applied ONLY where mask > 0 (the inpainted fills).

    frames : [B,3,H,W] float 0-1 (RGB)
    mask   : [B,1,H,W] float 0-1, the feathered blend mask (processed_mask).
             Grain strength follows the mask, so it fades exactly where the
             inpaint blend fades — no seams at fill boundaries.

    Model vs. plain Gaussian noise:
      * grain_size    — noise field blurred to sigma px so grain clumps like
                        film instead of 1-px digital speckle, then renormalized
                        to unit std so 'amount' is size-independent.
      * luma_falloff  — grain peaks in mid-tones and falls off toward shadows
                        and highlights (1 - falloff*(2L-1)^2), like negative film.
      * chroma_amount — grain is mostly shared-luma with a small independent
                        per-channel component; avoids rainbow speckle.
    A fresh field is drawn per frame so grain animates like film.

    `noise` : optional (noise_l, noise_c) from make_grain_field(). Pass the same
    tuple to both eyes of a stereo pair so the grain is interocularly correlated
    (screen-plane grain, no rivalry). None = draw a fresh field, as before.
    """
    if amount <= 0.0 or mask is None:
        return frames
    b, _, h, w = frames.shape
    dev, dt = frames.device, frames.dtype
    if noise is not None:
        noise_l, noise_c = noise
    else:
        noise_l, noise_c = make_grain_field(b, h, w, grain_size, dev, dt, generator)
    luma = 0.299 * frames[:, 0:1] + 0.587 * frames[:, 1:2] + 0.114 * frames[:, 2:3]
    weight = (1.0 - float(luma_falloff) * (2.0 * luma - 1.0) ** 2).clamp(0.0, 1.0)
    chroma_amount = float(max(0.0, min(1.0, chroma_amount)))
    grain = noise_l * (1.0 - chroma_amount) + noise_c * chroma_amount
    return (frames + grain * (float(amount) * weight * mask)).clamp(0.0, 1.0)


def _mad_sigma(x: torch.Tensor) -> float:
    """Robust sigma from the median absolute deviation, Gaussian-consistent.

    Edges and fine detail inside a measurement window are sparse, high-amplitude
    outliers. std() chases them, which is why a std-based reading of a thin
    occlusion sliver comes back far above the grain that is actually there. The
    median does not move until outliers pass 50% of the sample, and 1.4826 is
    the constant that makes MAD equal sigma for normal (i.e. grain) data.
    """
    if x.numel() < 16:
        return 0.0
    med = x.median()
    return float((x - med).abs().median().item()) * 1.4826


def _block_mad(resid: torch.Tensor, valid: torch.Tensor, bs: int, min_cov: float):
    """Per-block MAD sigma for every bs x bs block with >= min_cov valid pixels.

    Vectorised via reshape rather than a Python loop over blocks: at bs=8 on a
    1080p frame that loop is ~32k iterations per measurement, and this runs on
    every slider drag. Blocks are allowed a minority of out-of-mask pixels
    because MAD tolerates up to 50% contamination by construction — which is
    what lets a thin, feathered fill mask produce usable blocks at all.

    Returns a 1-D tensor of block sigmas, or None if fewer than 4 blocks qualify.
    """
    hh, ww = resid.shape
    ny, nx = hh // bs, ww // bs
    if ny == 0 or nx == 0:
        return None
    r = resid[: ny * bs, : nx * bs].reshape(ny, bs, nx, bs).permute(0, 2, 1, 3).reshape(ny * nx, bs * bs)
    v = valid[: ny * bs, : nx * bs].reshape(ny, bs, nx, bs).permute(0, 2, 1, 3).reshape(ny * nx, bs * bs)
    keep = v.float().mean(dim=1) >= min_cov
    if int(keep.sum().item()) < 4:
        return None
    r = r[keep]
    med = r.median(dim=1, keepdim=True).values
    mad = (r - med).abs().median(dim=1).values * 1.4826
    mad = mad[mad > 0]
    return mad if mad.numel() >= 4 else None


def measure_grain_sigma(
    frame_3hw: torch.Tensor,
    region_mask=None,
    blur_sigma: float = None,
    grain_size: float = None,
    luma_ref: float = None,
) -> float:
    """Estimate grain strength (robust sigma of the high-frequency luma residual, 0-1).

    The master path and the masked-fill path run the IDENTICAL estimator:
    per-block MAD, 25th percentile across blocks. That symmetry is the whole
    point. The previous version measured the master as a p25 of per-block stds
    but silently fell back to a plain std over all masked pixels whenever the
    fill was too thin to contain four fully-enclosed 24 px blocks — which is
    almost always, since disocclusion fills are slivers along depth edges. A
    detail-robust reading was being compared against a detail-inflated one, so
    a visibly smooth VAE fill could measure *noisier* than the grainy plate and
    Auto-Match would conclude there was nothing to add.

    blur_sigma : high-pass cutoff. Defaults from `grain_size` — a fixed 1.5 px
        cutoff passes 0.7 px grain fine but progressively misses coarser grain,
        so the readout would sag as Size went up even though the grain got
        stronger.
    luma_ref : if given, only measure where luma is within +/-0.18 of this.
        Grain sigma is strongly luma-dependent (both in real negative film and
        in our own falloff model), so an unbanded p25 over a whole frame lands
        in the darkest, flattest blocks and sets a target no mid-tone fill can
        reach. Pass the fill's median luma to compare like with like.
    """
    f = frame_3hw.float()
    if blur_sigma is None:
        g = 1.2 if grain_size is None else float(grain_size)
        blur_sigma = max(1.5, 2.0 * g)
    luma_t = (0.299 * f[0:1] + 0.587 * f[1:2] + 0.114 * f[2:3]).unsqueeze(0)
    resid = (luma_t - _gauss_blur_nchw(luma_t, blur_sigma)).squeeze(0).squeeze(0)
    luma = luma_t.squeeze(0).squeeze(0)

    if region_mask is not None:
        valid = region_mask.squeeze() > 0.5
    else:
        valid = torch.ones_like(resid, dtype=torch.bool)
    if int(valid.sum().item()) <= 64:
        return 0.0

    if luma_ref is not None:
        band = (luma - float(luma_ref)).abs() <= 0.18
        if int((valid & band).sum().item()) > 256:
            valid = valid & band

    # Shrink the window until enough blocks fit inside the region. Bigger blocks
    # give a steadier MAD, so try those first and only step down for thin fills.
    for bs, min_cov in ((24, 0.90), (16, 0.85), (12, 0.80), (8, 0.75)):
        mad = _block_mad(resid, valid, bs, min_cov)
        if mad is not None:
            return float(torch.quantile(mad, 0.25).item())
    # Last resort: MAD over the region as a whole. Still robust — unlike the
    # std() this used to fall back to.
    return _mad_sigma(resid[valid])


def apply_fill_color_correction(
    frames: torch.Tensor, mask: torch.Tensor, brightness: float, contrast: float
) -> torch.Tensor:
    """Brightness/contrast correction on the inpainted fills only.

    corrected = (frames - 0.5) * contrast + 0.5 + brightness, blended in by the
    feathered mask so the correction fades exactly where the fill fades.
    brightness 0.0 and contrast 1.0 are a no-op. frames [B,3,H,W], mask [B,1,H,W].
    """
    if mask is None or (abs(brightness) < 1e-4 and abs(contrast - 1.0) < 1e-4):
        return frames
    corrected = ((frames - 0.5) * float(contrast) + 0.5 + float(brightness)).clamp(0.0, 1.0)
    return (frames + mask * (corrected - frames)).clamp(0.0, 1.0)


def apply_fill_red_reduction(frames: torch.Tensor, mask: torch.Tensor, strength: float) -> torch.Tensor:
    """Tone down red OVERSHOOT in the inpainted fills (VAE red-flare tamer).

    One-sided pull of the red channel toward luma, only where R exceeds luma:
        R' = R - strength * mask * max(R - luma, 0)
    Red-excess pixels desaturate toward neutral; neutrals, skin-consistent and
    non-red pixels are untouched; effect feathers with the blend mask.
    frames [B,3,H,W] RGB 0-1, mask [B,1,H,W] 0-1.
    """
    if strength <= 0.0 or mask is None:
        return frames
    luma = 0.299 * frames[:, 0:1] + 0.587 * frames[:, 1:2] + 0.114 * frames[:, 2:3]
    excess = (frames[:, 0:1] - luma).clamp_min(0.0)
    out = frames.clone()
    out[:, 0:1] = frames[:, 0:1] - float(strength) * mask * excess
    return out.clamp(0.0, 1.0)


GRAIN_PARAM_KEYS = ("grain_enable", "grain_amount", "grain_size", "grain_luma_falloff", "grain_chroma", "grain_seed", "fill_red_reduce", "fill_brightness", "fill_contrast")


def apply_mask_highlight(frames: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
    """Visualize the processed mask ON the image, tuning-oriented:

    * Magenta tint whose opacity FOLLOWS the mask value — so blur feathering,
      shadow decay and dilation growth are directly visible as tint gradients
      when the sliders move (not just a hard region).
    * Bright green 1px outline at the 0.5 boundary — the exact cutout edge.

    frames [B,3,H,W] 0-1, mask [B,1,H,W] 0-1. Returns highlighted frames.
    """
    tint = torch.tensor([1.0, 0.15, 0.9], device=frames.device, dtype=frames.dtype).view(1, 3, 1, 1)
    a = 0.45 * mask  # tint opacity tracks the feathered mask value
    out = frames * (1.0 - a) + tint * a
    hard = (mask > 0.5).float()
    edge = (F.max_pool2d(hard, 3, stride=1, padding=1) - hard).clamp(0, 1)
    edge_c = torch.tensor([0.15, 1.0, 0.2], device=frames.device, dtype=frames.dtype).view(1, 3, 1, 1)
    out = out * (1.0 - edge) + edge_c * edge
    return out.clamp(0.0, 1.0)


def process_blend_mask(mask: torch.Tensor, settings: dict, use_gpu: bool) -> torch.Tensor:
    """Binarize -> dilate -> blur -> shadow: the standard blend-mask chain.

    Factored out so the dual-eye grain path uses the byte-identical chain the
    single-eye blend uses — otherwise a later tweak to one would silently leave
    the other behind. `settings` may be the batch settings dict or the popup's
    params dict; both carry the same keys.
    """
    d = MergingGUI.APP_DEFAULTS
    pm = mask.clone()
    if float(settings.get("mask_binarize_threshold", d["mask_binarize_threshold"])) >= 0.0:
        pm = (mask > float(settings["mask_binarize_threshold"])).float()
    if float(settings.get("mask_dilate_kernel_size", d["mask_dilate_kernel_size"])) > 0:
        pm = apply_mask_dilation(pm, settings["mask_dilate_kernel_size"], use_gpu)
    if float(settings.get("mask_blur_kernel_size", d["mask_blur_kernel_size"])) > 0:
        pm = apply_gaussian_blur(pm, settings["mask_blur_kernel_size"], use_gpu)
    if float(settings.get("shadow_shift", d["shadow_shift"])) > 0:
        pm = apply_shadow_blur(
            pm,
            settings["shadow_shift"],
            settings["shadow_start_opacity"],
            settings["shadow_opacity_decay"],
            settings["shadow_min_opacity"],
            settings["shadow_decay_gamma"],
            use_gpu,
        )
    return pm


def apply_fill_fx(
    eye: torch.Tensor,
    pm: torch.Tensor,
    grain_params: dict,
    noise=None,
    generator=None,
) -> torch.Tensor:
    """Fill color correction + red-flare tamer + masked grain, in render order.

    The three fill treatments always travel together and are always weighted by
    the same feathered mask, so they live in one call. `noise` lets a stereo
    pair share a grain field.
    """
    if abs(grain_params["brightness"]) > 1e-4 or abs(grain_params["contrast"] - 1.0) > 1e-4:
        eye = apply_fill_color_correction(
            eye, pm, grain_params["brightness"], grain_params["contrast"]
        )
    if grain_params["red_reduce"] > 0:
        eye = apply_fill_red_reduction(eye, pm, grain_params["red_reduce"])
    if grain_params["enable"]:
        eye = apply_film_grain_masked(
            eye,
            pm,
            amount=grain_params["amount"],
            grain_size=grain_params["size"],
            luma_falloff=grain_params["luma_falloff"],
            chroma_amount=grain_params["chroma"],
            generator=generator,
            noise=noise,
        )
    return eye


def _fill_fx_slice(frames: int, h: int, w: int) -> int:
    """Frames per GPU slice: ~12 floats a pixel live at once (eye, mask,
    luma + chroma noise, blur temporaries), within 1.5 GB and a quarter of
    what is free."""
    free, _total = torch.cuda.mem_get_info()
    per_frame = h * w * 4 * 12
    return max(1, min(frames, int(min(1.5 * 2 ** 30, free * 0.25) // per_frame)))


def fill_fx_on_gpu(settings: dict) -> bool:
    return bool(settings.get("grain_gpu", True)) and torch.cuda.is_available()


def apply_fill_fx_gpu(eye, pm, grain_params, generator=None):
    """apply_fill_fx on the GPU for CPU frames, slice by slice, back on the
    CPU (v2, user 2026-09-29)."""
    b, _, h, w = eye.shape
    step = _fill_fx_slice(b, h, w)
    out = []
    for i in range(0, b, step):
        e, m = eye[i:i + step].cuda(), pm[i:i + step].cuda()
        out.append(apply_fill_fx(e, m, grain_params, generator=generator).cpu())
        del e, m
    return torch.cat(out)


def apply_fill_fx_pair_gpu(left, right, lpm, rpm, grain_params, generator=None):
    """The dual-eye fill treatments on the GPU, slice by slice: ONE grain
    field per slice for both eyes, as the CPU path shares one per chunk."""
    b, _, h, w = left.shape
    step = _fill_fx_slice(b, h, w * 2)
    outs_l, outs_r = [], []
    for i in range(0, b, step):
        l, r = left[i:i + step].cuda(), right[i:i + step].cuda()
        lm, rm = lpm[i:i + step].cuda(), rpm[i:i + step].cuda()
        noise = None
        if grain_params["enable"]:
            noise = make_grain_field(l.shape[0], h, w, grain_params["size"], l.device, l.dtype, generator)
        outs_l.append(apply_fill_fx(l, lm, grain_params, noise=noise).cpu())
        outs_r.append(apply_fill_fx(r, rm, grain_params, noise=noise).cpu())
        del l, r, lm, rm, noise
    return torch.cat(outs_l), torch.cat(outs_r)


def detect_mask_panel_side(frame_hw3_uint8: np.ndarray) -> str:
    """Which column half of a _splatted2D row holds the MASK panel: 'left'/'right'.

    The documented layout is [Lmask|Lwarp] / [Rmask|Rwarp], but reading the warp
    panel as a mask would grain the whole frame by picture brightness with no
    visible error message — so this checks rather than assumes. A mask panel is
    near-bimodal (almost every pixel at 0 or 1); a warped picture panel is not.
    Returns 'left' when ambiguous, matching the documented layout.
    """
    h, w = frame_hw3_uint8.shape[0], frame_hw3_uint8.shape[1]
    top = frame_hw3_uint8[: h // 2]
    left = top[:, : w // 2].astype(np.float32).mean(axis=2) / 255.0
    right = top[:, w // 2 :].astype(np.float32).mean(axis=2) / 255.0

    def _bimodality(a):
        # Fraction of pixels sitting in the extreme 6% of the range.
        return float(((a < 0.06) | (a > 0.94)).mean())

    bl, br = _bimodality(left), _bimodality(right)
    if bl > br + 0.15:
        return "left"
    if br > bl + 0.15:
        return "right"
    return "left"


