def resolve_grain_params(settings: dict, sidecar: dict) -> dict:
    """Per-clip grain params: sidecar value wins over the GUI/global setting."""
    sc = sidecar or {}
    def _f(key, cast):
        v = sc.get(key, settings.get(key))
        try:
            return cast(v)
        except (TypeError, ValueError):
            return cast(MergingGUI.APP_DEFAULTS[key])
    return {
        "enable": bool(sc.get("grain_enable", settings.get("grain_enable", False))),
        "amount": _f("grain_amount", float),
        "size": _f("grain_size", float),
        "luma_falloff": _f("grain_luma_falloff", float),
        "chroma": _f("grain_chroma", float),
        "seed": _f("grain_seed", int),
        "red_reduce": _f("fill_red_reduce", float),
        "brightness": _f("fill_brightness", float),
        "contrast": _f("fill_contrast", float),
    }


