class _Var:
    """Stands in for a tk variable: one key of the engine's values. Writes to
    the display-only vars (progress, clip info, status) go to the hooks."""

    def __init__(self, engine, key):
        self._engine = engine
        self._key = key

    def get(self):
        return self._engine._values.get(self._key)

    def set(self, value):
        self._engine._values[self._key] = value
        self._engine.hooks.var(self._key, value)


