class _MessageBoxShim:
    """v1's tkinter.messagebox as prompts in the page; askyesno answers with
    ``answer``, which the caller sets after asking in QML."""

    def __init__(self):
        self.hooks = None
        self.answer = False

    def _send(self, kind, title, message):
        if self.hooks is not None:
            self.hooks.message(kind, str(title), str(message))
        else:
            logger.warning("%s: %s", title, message)

    def showerror(self, title="", message="", **_kw):
        self._send("error", title, message)

    def showwarning(self, title="", message="", **_kw):
        self._send("warning", title, message)

    def showinfo(self, title="", message="", **_kw):
        self._send("info", title, message)

    def askyesno(self, title="", message="", **_kw):
        return bool(self.answer)


messagebox = _MessageBoxShim()


def _wait_for_encoder(process, stop_event, poll: float = 2.0) -> None:
    """Wait for ffmpeg to finish its file, however long the flush takes -- a CPU
    x265 at a slow preset still holds its lookahead after the last frame -- and
    give up only on Stop (bug sweep 2026-10-09, A8: a fixed 120 s killed and
    discarded finished merges). Stop raises TimeoutExpired, as the old limit did,
    so the clip's own clean-up ends the encoder."""
    while True:
        try:
            process.wait(timeout=poll)
            return
        except subprocess.TimeoutExpired:
            if stop_event.is_set():
                raise


