        """How the batch ended, told once (audit #3): the toast, and whether
        its output is handed on. A clip that failed stops v1's batch, so an
        error outranks the stop it caused."""
        if getattr(self, "_asked_missing", False):
            # the page is asking about missing originals (user, 2026-10-09): nothing
            # ran, and the answer starts it again -- no toast, no notification
            self._asked_missing = False
            import types
            return types.SimpleNamespace(kind="info", title="Waiting: some clips have no original",
                                         text="", handoff=False)
        o = self.outcome
        v = verdict("Merging", o, stopped=bool(stopped) and not o.error)
        toast = getattr(self.hooks, "toast", None)
