    # -- v1 MergingGUI._merge_resize_inpaint (merging_gui.py:2242)
    def _merge_resize_inpaint(self, inpainted, mask, hires_H, hires_W):
        """Resize inpaint+mask to the target per-eye dims, preserving aspect ratio.

        Factored out of the merge blend loop. Returns (inpainted, mask) unchanged
        if already at target size.
        """
        if inpainted.shape[2] == hires_H and inpainted.shape[3] == hires_W:
            return inpainted, mask

        target_aspect = hires_W / hires_H
        inpaint_aspect = inpainted.shape[3] / inpainted.shape[2]

        if abs(inpaint_aspect - target_aspect) > 0.01:
            logger.debug(
                f"Inpaint aspect ratio ({inpaint_aspect:.4f}) differs from target ({target_aspect:.4f}). "
                f"Resizing from {inpainted.shape[3]}x{inpainted.shape[2]} to fit {hires_W}x{hires_H}."
            )
            if inpaint_aspect > target_aspect:
                new_w = hires_W
                new_h = int(round(hires_W / inpaint_aspect))
            else:
                new_h = hires_H
                new_w = int(round(hires_H * inpaint_aspect))
            inpainted = F.interpolate(inpainted, size=(new_h, new_w), mode="bicubic", align_corners=False)
            mask = F.interpolate(mask, size=(new_h, new_w), mode="bilinear", align_corners=False)

        inpainted = F.interpolate(inpainted, size=(hires_H, hires_W), mode="bicubic", align_corners=False)
        mask = F.interpolate(mask, size=(hires_H, hires_W), mode="bilinear", align_corners=False)
        return inpainted, mask

    # -- v1 MergingGUI._apply_frame_break_pair (merging_gui.py:2272)
    def _apply_frame_break_pair(self, left, right, mask_np, bars_amount, H, W):
        """Frame Break: burn letterbox bars into both eyes, compositing the
        protrusion mask as a SOFT alpha.

        The mask (0..255) is treated as alpha, not a binary cutout: 255 keeps
        the subject at full strength, 0 is solid black bar, and intermediate
        values are the feathered break boundary that Frame Break's Edge Blur
        baked into the written mask at render time. With Edge Blur off the mask
        is flat 0/255, so this reduces to the original hard cutout. Erode/dilate
        of the mask edges is likewise already baked in -- merging just stamps
        whatever shape it is handed.

        Args:
            left, right: [B, 3, H', W'] float tensors in [0, 1] (original_left,
                blended_right_eye at this point in run_batch_process).
            mask_np: [B, mh, mw] uint8 (0 or 255), read from this clip's
                Frame Break mask video. Resized NEAREST to (H, W) if its
                resolution doesn't match -- nearest keeps the cutout hard
                instead of blending a soft edge in via interpolation.
            bars_amount: this clip's frame_break_bars (0..1 fraction of H).
            H, W: the eyes' own per-frame height/width (left/right must
                already be at this size -- this method does not resize them).

        Returns:
            (left, right) with bars applied. Unchanged (same objects) if
            bars_amount rounds to 0 rows.
        """
        bar_px = int(round(float(bars_amount) * 0.5 * H))
        bar_px = min(bar_px, H // 2 if H > 1 else 0)
        if bar_px <= 0:
            return left, right

        B = left.shape[0]
        mh, mw = mask_np.shape[1], mask_np.shape[2]
        if (mh, mw) != (H, W):
            resized = np.empty((B, H, W), dtype=np.uint8)
            for k in range(B):
                # LINEAR, not NEAREST: the mask may carry a feathered break edge
                # (Frame Break's Edge Blur), baked in at render time. Nearest
                # here would re-harden it. A hard mask (no blur) is unaffected --
                # its interior is flat 0/255 and only the 1px boundary softens,
                # which is negligible.
                resized[k] = cv2.resize(mask_np[k], (W, H), interpolation=cv2.INTER_LINEAR)
            mask_np = resized

        # Soft alpha, NOT a binary threshold: 255 -> show subject, 0 -> solid
        # bar, intermediate -> feathered break edge. Re-binarizing here would
        # throw away the Edge Blur that was baked into the written mask.
        alpha = torch.from_numpy(mask_np.astype(np.float32) / 255.0).to(device=left.device)
        alpha = alpha.unsqueeze(1)  # [B, 1, H, W] -- broadcasts over RGB

        def _stamp(frame):
            out = frame.clone()
            for region in (slice(0, bar_px), slice(H - bar_px, H)):
                # bar is black, so result = subject*alpha + black*(1-alpha).
                out[:, :, region, :] = out[:, :, region, :] * alpha[:, :, region, :]
            return out

        return _stamp(left), _stamp(right)

