    def holds_gpu(self) -> bool:
        """True while this stage has CUDA state resident."""
        if getattr(self, "_preview_stereo_projector", None) is not None:
            return True
        return bool(self.is_processing)

    # -- v1 MergingGUI.release_gpu (merging_gui.py:2714)
    def release_gpu(self) -> None:
        """Drop preview CUDA state and empty the cache. Idempotent."""
        if self.is_processing:
            logger.warning("Merging asked to release GPU while processing; ignoring")
            return
        if getattr(self, "_preview_stereo_projector", None) is not None:
            try:
                del self._preview_stereo_projector
            except Exception:
                pass
            self._preview_stereo_projector = None
        try:
            release_cuda_memory()
        except Exception:
            logger.debug("release_cuda_memory unavailable", exc_info=True)

    # -- v1 MergingGUI.stop_processing (merging_gui.py:2730)
    def stop_processing(self):
        if self.is_processing:
            self.stop_event.set()
            self.update_status_label("Stopping...")

    # -- v1 MergingGUI.process_current_clip (merging_gui.py:2735)
    def process_current_clip(self):
        """Process the currently selected clip only."""
        if self.is_processing:
            messagebox.showwarning("Busy", "Processing is already in progress.")
            return

        # Get current video from previewer
        if not hasattr(self, "previewer") or not self.previewer.video_list:
            messagebox.showwarning("No Video", "No video loaded in previewer.")
            return

        current_index = getattr(self.previewer, "current_video_index", 0)
        if current_index < 0 or current_index >= len(self.previewer.video_list):
            messagebox.showwarning("Invalid Index", "No video selected.")
            return

        source_dict = self.previewer.video_list[current_index]
        inpainted_path = source_dict.get("inpainted")

        if not inpainted_path or not os.path.exists(inpainted_path):
            messagebox.showwarning("Invalid Path", "Inpainted video path not found.")
            return

        # Get current settings
        settings = self.get_current_settings()
        if not settings:
            return

        # Temporarily set inpainted_folder to just this file's directory
        settings["inpainted_folder"] = os.path.dirname(inpainted_path)

        if not self._claim_job():
            return
        self.is_processing = True
        self.stop_event.clear()
        self._set_ui_processing_state(True)
        self._clear_preview_resources()
        base_name = os.path.basename(inpainted_path)
        self.update_status_label(f"Processing single clip: {base_name}")

        # Run in a separate thread using the existing batch processor
        # Pass the specific video path to process only this one
        self.processing_thread = threading.Thread(
            target=self.run_batch_process, args=(settings, inpainted_path), daemon=True
        )
        self.processing_thread.start()

    # -- v1 MergingGUI._record_job_handoff (merging_gui.py:3062)
    def _record_job_handoff(self):
        """Remember this job's paths for the next stage's import button."""
        try:
            from core.ui.job_handoff import record_job

            record_job("merging", {
                "merged_out": self.output_folder_var.get(),
            })
        except Exception:
            logger.debug("Could not record job handoff", exc_info=True)

    # -- v1 MergingGUI.is_busy (merging_gui.py:3073)
    def is_busy(self) -> bool:
        """True while a merge OR its file cleanup is still running.

        The cleanup thread outlives the encode: it drains cleanup_queue, moving
        consumed sources and masks into finished/ with retry-on-lock sleeps of
        up to 3s. processing_done() used to report idle the moment the encode
        ended, so the shell could close the app mid-move and process exit would
        kill the thread partway through.
        """
        if self.is_processing:
            return True
        thread = getattr(self, "cleanup_thread", None)
        return bool(thread is not None and thread.is_alive())

    # -- v1 MergingGUI.processing_done (merging_gui.py:3087)
    def processing_done(self, stopped=False):
        self.is_processing = False
        self.cleanup_queue.put(None)  # v2: see gen_merging_engine PATCHES
        # Every path out of processing lands here, which makes it the one place
        # the shell's job claim can be released without missing a case.
        self._release_job()
        _verdict = self._finish_verdict(stopped)  # v2: see gen_merging_engine PATCHES
        if _verdict.handoff:
            self._record_job_handoff()
        self._set_ui_processing_state(False)  # Re-enable UI
        if _verdict.kind == "error":  # v2: bug sweep A8 -- the verdict, not just `stopped`
            message = _verdict.title + "."
        elif stopped:
            message = "Processing stopped."
        elif _verdict.kind == "success":
            message = "Processing completed."
        else:
            message = _verdict.title + "."
        self.update_status_label(message)
        self.progress_var.set(0)
        self.processing_clip_count_var.set("—")
        self._clear_border_info()
        # The panel followed the batch; give it back to the previewer.
        self._update_info_display()
        if hasattr(self, "previewer"):
            self.previewer.reset_video_list_scan()

        # --- NEW: Schedule VRAM release after a short delay to ensure stability ---
        delay_ms = 2000  # 2 seconds
        logger.info(f"Scheduling VRAM release in {delay_ms / 1000} seconds...")
        self.after(delay_ms, release_cuda_memory)

